import React, { useState } from "react";
import { IoIosArrowDropdownCircle } from "react-icons/io";
import BackToHome from "../components/BackToHome";
import { useLocation, useNavigate } from "react-router-dom";
import { getTravelMonthRange } from "./Booking";
import axios from "axios";
import { API_URL } from "../AppConstant";
import Swal from "sweetalert2";

function VeiwBooking() {

  const [active, setActive] = useState(0); // Section toggle

  const [airTicket, setAirTicket] = useState([])
  const [passport, setPassport] = useState([])
  const [pan, setPan] = useState([])
  const [misc, setMisc] = useState([])
  const [emailConf, setEmailConf] = useState([])

  const addAirTicker = (e) => {
    const file = e.target.files[0];
    const fileURL = URL.createObjectURL(file)
    setAirTicket(...airTicket, {file: file, url: fileURL})
    console.log(airTicket, 'airTicket');
  }
  
  const addPassport = (e) => {
    const file = e.target.files[0];
    const fileURL = URL.createObjectURL(file)
    setPassport(...passport, {file: file, url: fileURL})
    console.log(passport, 'airTicket');
  }

  const addPan = (e) => {
    const file = e.target.files[0];
    const fileURL = URL.createObjectURL(file)
    setPan(...pan, {file: file, url: fileURL})
    console.log(pan, 'airTicket');
  }

  const addMisc = (e) => {
    const file = e.target.files[0];
    const fileURL = URL.createObjectURL(file)
    setMisc(...misc, {file: file, url: fileURL})
    console.log(misc, 'airTicket');
  } 

  const addEmailConf = (e) => {
    const file = e.target.files[0];
    const fileURL = URL.createObjectURL(file)
    setEmailConf(...emailConf, {file: file, url: fileURL})
    console.log(emailConf, 'airTicket');
  }

  const removeAirTicket = (index) => {
    const updatedDoc = airTicket.filter((_, i) => i !== index);
    setAirTicket(updatedDoc)
  }

  const removePassport = (index) => {
    const updatedDoc = passport.filter((_, i) => i !== index);
    setPassport(updatedDoc)
  }

  const removePan = (index) => {
    const updatedDoc = pan.filter((_, i) => i !== index);
    setPan(updatedDoc)
  }

  const removeMisc = (index) => {
    const updatedDoc = misc.filter((_, i) => i !== index);
    setMisc(updatedDoc)
  }

  const removeEmailConf = (index) => {
    const updatedDoc = emailConf.filter((_, i) => i !== index);
    setEmailConf(updatedDoc)
  }

  const location = useLocation();
  const data = location.state;
  console.log(data, 'data');

  const navigate = useNavigate();

  // Accept Booking is to set booking status to confirmed also add salesSpoc
  const acceptBooking = async() => {
    await submit();
    alert("Booking accepted and saved!");
  };

  // Reject Booking is to delete the booking
  const rejectBooking = async() => {
   try {
    console.log(data.booking_id, 'booking id');
     const response = await axios.delete(`${API_URL}users/deleteBooking/${data.booking_id}`,{
      withCredentials: true,
      headers: {
        "Content-Type": "application/json",
      },
    })
    if (response.status === "ok") {
      alert("Booking has been deleted successfully");
      navigate('/booking')
    } else {
      alert("Error deleting booking. Please try again later.");
      navigate('/booking')
    }
   } catch (error) {
    console.log(error);
   }
  };

  const submit = async () => {
    Swal.fire("submit data")
    // const axios.post(`${API_URL}users/uploadDocuments`, doc,
    // {
    //   withCredentials: true,
    //   headers: {
    //     "Content-Type": "application/json",
    //   },
    // })
    }
    // write your logic here

  return (
    <div className="p-4">
    <BackToHome path="/booking" />
      <div className="max-w-4xl mx-auto p-4 md:p-6 bg-white shadow-lg rounded-lg mt-8">
        <h1 className="text-2xl font-bold text-center mb-6">View Booking</h1>

        {/* Booking Details */}
        <div className="mb-6">
          <h2 className="text-lg font-semibold bg-gray-200 p-2 rounded flex justify-between">
            Booking Details
            <span onClick={() => setActive(active === 0 ? null : 0)}>
              <IoIosArrowDropdownCircle />
            </span>
          </h2>
          <div className={`${active === 0 ? "block" : "hidden"} grid grid-cols-2 gap-4 p-4`}>
            {[
              ["Destination", data.destination],
              ["Sales Spoc", data.salesSpoc],
              ["Agent", data.agent],
              ["Customer Name", data.customerName],
              ["Number of Pax", data.pax.A + data.pax.C],
              ["Travel Month", getTravelMonthRange(data.arrivalDate, data.departureDate)],
              ["Arrival Date", data.arrivalDate],
              ["Departure Date", data.departureDate],
              ["Booking Date", data.bookingDate],
              ["WhatsApp Number",data.countryCode + " " + data.whatsappNumber],
              ["Ops Spoc", "some One"], // ask client where will this come from
            ].map(([label, value], index) => (
              <div key={index} className="flex space-x-3">
                <label className="font-semibold">{label}:</label>
                <p>{value}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Document Upload */}
        <div className="mb-6">
          <h2 className="text-lg font-semibold bg-gray-200 p-2 rounded flex justify-between">
            Document Upload
            <span onClick={() => setActive(active === 1 ? null : 1)}>
              <IoIosArrowDropdownCircle />
            </span>
          </h2>
          <div className={`p-4 ${active === 1 ? "block" : "hidden"}`}>
            <div className="flex">
              {/* Document Upload List */}
              <div className="w-1/2 border-r-2 pr-4">
                <ul>
                    <li className="flex justify-between mb-2">
                      <span>Air Ticket:</span>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        className="hidden"
                        id="airTicket"
                        onChange={addAirTicker}
                      />
                      <label
                        htmlFor="airTicket"
                        className="bg-blue-600 text-white px-2 py-1 rounded-lg cursor-pointer hover:bg-blue-700"
                      >
                        Upload
                      </label>
                    </li>
                    <li className="flex justify-between mb-2">
                      <span>Passport:</span>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        className="hidden"
                        id={`passport`}
                        onChange={(e) => addPassport(e)}
                      />
                      <label
                        htmlFor={`passport`}
                        className="bg-blue-600 text-white px-2 py-1 rounded-lg cursor-pointer hover:bg-blue-700"
                      >
                        Upload
                      </label>
                    </li>
                    <li className="flex justify-between mb-2">
                      <span>PAN:</span>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        className="hidden"
                        id={`pan`}
                        onChange={(e) => addPan(e)}
                      />
                      <label
                        htmlFor={`pan`}
                        className="bg-blue-600 text-white px-2 py-1 rounded-lg cursor-pointer hover:bg-blue-700"
                      >
                        Upload
                      </label>
                    </li>
                    <li className="flex justify-between mb-2">
                      <span>Miscleanious:</span>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        className="hidden"
                        id={`misc`}
                        onChange={(e) => addMisc(e)}
                      />
                      <label
                        htmlFor={`misc`}
                        className="bg-blue-600 text-white px-2 py-1 rounded-lg cursor-pointer hover:bg-blue-700"
                      >
                        Upload
                      </label>
                    </li>
                    <li className="flex justify-between mb-2">
                      <span>Email Confirmation:</span>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        className="hidden"
                        id={`emailConf`}
                        onChange={(e) => addEmailConf(e)}
                      />
                      <label
                        htmlFor={`emailConf`}
                        className="bg-blue-600 text-white px-2 py-1 rounded-lg cursor-pointer hover:bg-blue-700"
                      >
                        Upload
                      </label>
                    </li>
                </ul>
              </div>
              {/* Document Preview */}
              <div className="w-1/2 pl-4">
                <h3 className="text-lg font-semibold mb-2">Air Tickets:</h3>
                {airTicket.map((doc, index) => (
                  <>
                  <a key={index} href={doc.url} target="_blank" rel="noopener noreferrer">
                    </a>
                    <button className="text-red-400" onClick={removeAirTicket(index)}></button>
                  </>
                ))}
                <h3 className="text-lg font-semibold mb-2">Passport:</h3>
                {passport.map((doc, index) => (
                  <>
                  <a key={index} href={doc.url} target="_blank" rel="noopener noreferrer">
                    </a>
                    <button className="text-red-400" onClick={removePassport(index)}></button>
                  </>
                ))}
                <h3 className="text-lg font-semibold mb-2">PAN:</h3>
                {pan.map((doc, index) => (
                  <>
                  <a key={index} href={doc.url} target="_blank" rel="noopener noreferrer">
                    </a>
                    <button className="text-red-400" onClick={removePan(index)}></button>
                  </>
                ))}
                <h3 className="text-lg font-semibold mb-2">Miscleanious:</h3>
                {misc.map((doc, index) => (
                  <>
                  <a key={index} href={doc.url} target="_blank" rel="noopener noreferrer">
                    </a>
                    <button className="text-red-400" onClick={removeMisc(index)}></button>
                  </>
                ))}
                <h3 className="text-lg font-semibold mb-2">Email Confirmation:</h3>
                {emailConf.map((doc, index) => (
                  <>
                  <a key={index} href={doc.url} target="_blank" rel="noopener noreferrer">
                    </a>
                    <button className="text-red-400" onClick={removeEmailConf(index)}></button>
                  </>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Commercials */}
        <div className="mb-6">
          <h2 className="text-lg font-semibold bg-gray-200 p-2 rounded flex justify-between">
            Commercials
            <span onClick={() => setActive(active === 2 ? null : 2)}>
              <IoIosArrowDropdownCircle />
            </span>
          </h2>
          <div className={`p-4 ${active === 2 ? "block" : "hidden"}`}>
            <label className="font-semibold">Order Value (USD):</label>
            <input
              type="text"
              value={data.orderValue}
              // onChange={(e) => setdata({ ...data, orderValue: e.target.value })}
              className="w-full p-2 border rounded mt-2"
            />
          </div>
        </div>

        {/* Freeze Quotation */}
        <div className="mb-6">
          <h2 className="text-lg font-semibold bg-gray-200 p-2 rounded flex justify-between">
            Freeze Quotation
            <span onClick={() => setActive(active === 3 ? null : 3)}>
              <IoIosArrowDropdownCircle />
            </span>
          </h2>
          <div className={`p-4 ${active === 3 ? "block" : "hidden"}`}>
          <span>Freeze Quotation:</span>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        className="hidden"
                        id={`file-quatation`}
                        // onChange={(e) => handleFileUpload(e, {docName: "quatation"})}
                      />
                      <label
                        htmlFor={`file-quatation`}
                        className="bg-blue-600 text-white px-2 mx-4 py-1 rounded-lg cursor-pointer hover:bg-blue-700"
                      >
                        Upload
                      </label>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="p-4 flex justify-between">
          <button
            onClick={acceptBooking}
            className="bg-green-500 text-white px-6 py-2 rounded hover:bg-green-600"
          >
            Accept Booking
          </button>
          <button
            onClick={rejectBooking}
            className="bg-red-500 text-white px-6 py-2 rounded hover:bg-red-600"
          >
            Reject Booking
          </button>
        </div>
      </div>
    </div>
  );
}

export default VeiwBooking;
